using System;
using System.Linq;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

namespace ForgeBench
{
    public sealed class ProgressionPanel : MonoBehaviour
    {
        private static ProgressionPanel instance;
        private GameObject root;private RectTransform content;private Font font;private int page;
        public static void Open(int p=0){if(instance==null){GameObject g=new GameObject("ForgeBench_ProgressionPanel");DontDestroyOnLoad(g);instance=g.AddComponent<ProgressionPanel>();}instance.page=Mathf.Clamp(p,0,2);instance.Show();}
        public static void RefreshIfOpen(){if(instance!=null&&instance.root!=null&&instance.root.activeSelf)instance.Refresh();}
        private void Awake(){if(instance!=null&&instance!=this){Destroy(gameObject);return;}instance=this;DontDestroyOnLoad(gameObject);font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");EnsureEventSystem();Build();root.SetActive(false);}
        private void Update(){if(root!=null&&root.activeSelf&&Input.GetKeyDown(KeyCode.Escape)&&!Application.isMobilePlatform)Close();}
        private void Show(){root.SetActive(true);Cursor.lockState=CursorLockMode.None;MobileInputState.Move=Vector2.zero;Refresh();}
        private void Close(){root.SetActive(false);Cursor.lockState=CursorLockMode.Locked;}
        private void Build(){root=new GameObject("ProgressionRoot",typeof(RectTransform));root.transform.SetParent(transform,false);Canvas c=root.AddComponent<Canvas>();c.renderMode=RenderMode.ScreenSpaceOverlay;c.sortingOrder=25360;CanvasScaler sc=root.AddComponent<CanvasScaler>();sc.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;sc.referenceResolution=new Vector2(1920,1080);sc.matchWidthOrHeight=.5f;root.AddComponent<GraphicRaycaster>();GameObject bg=UI("BG",root.transform);Stretch(bg.GetComponent<RectTransform>());bg.AddComponent<Image>().color=new Color(.014f,.020f,.029f,.995f);GameObject panel=UI("Panel",bg.transform);RectTransform pr=panel.GetComponent<RectTransform>();pr.anchorMin=new Vector2(.055f,.05f);pr.anchorMax=new Vector2(.945f,.95f);pr.offsetMin=pr.offsetMax=Vector2.zero;panel.AddComponent<Image>().color=new Color(.052f,.064f,.08f,1f);GameObject header=UI("Header",panel.transform);RectTransform hr=header.GetComponent<RectTransform>();hr.anchorMin=new Vector2(0,1);hr.anchorMax=new Vector2(1,1);hr.pivot=new Vector2(.5f,1);hr.sizeDelta=new Vector2(0,84);hr.anchoredPosition=Vector2.zero;header.AddComponent<Image>().color=new Color(.072f,.087f,.105f,1f);Text title=Text("CAREER / CERTIFICATIONS",header.transform,30,TextAnchor.MiddleLeft,Color.white);RectTransform tr=title.rectTransform;tr.anchorMin=new Vector2(.025f,0);tr.anchorMax=new Vector2(.42f,1);tr.offsetMin=tr.offsetMax=Vector2.zero;string[] tabs={"CAREER","SKILLS","ACHIEVEMENTS"};for(int i=0;i<tabs.Length;i++){int capture=i;Button b=Button(tabs[i],header.transform,new Color(.12f,.15f,.19f,1f),()=>{page=capture;Refresh();});RectTransform r=b.GetComponent<RectTransform>();float x=.46f+i*.13f;r.anchorMin=new Vector2(x,.16f);r.anchorMax=new Vector2(x+.12f,.84f);r.offsetMin=r.offsetMax=Vector2.zero;}Button close=Button("✕",header.transform,new Color(.55f,.11f,.12f,1f),Close);RectTransform xr=close.GetComponent<RectTransform>();xr.anchorMin=new Vector2(.91f,.16f);xr.anchorMax=new Vector2(.975f,.84f);xr.offsetMin=xr.offsetMax=Vector2.zero;GameObject scrollGo=UI("Scroll",panel.transform);RectTransform sr=scrollGo.GetComponent<RectTransform>();sr.anchorMin=new Vector2(.02f,.025f);sr.anchorMax=new Vector2(.98f,.90f);sr.offsetMin=sr.offsetMax=Vector2.zero;ScrollRect scroll=scrollGo.AddComponent<ScrollRect>();scroll.horizontal=false;scroll.scrollSensitivity=42f;GameObject viewport=UI("Viewport",scrollGo.transform);Stretch(viewport.GetComponent<RectTransform>());viewport.AddComponent<Image>().color=new Color(.024f,.032f,.042f,.78f);Mask mask=viewport.AddComponent<Mask>();mask.showMaskGraphic=false;scroll.viewport=viewport.GetComponent<RectTransform>();GameObject body=UI("Content",viewport.transform);content=body.GetComponent<RectTransform>();content.anchorMin=new Vector2(0,1);content.anchorMax=new Vector2(1,1);content.pivot=new Vector2(.5f,1);content.sizeDelta=new Vector2(0,500);VerticalLayoutGroup vg=body.AddComponent<VerticalLayoutGroup>();vg.padding=new RectOffset(20,20,18,22);vg.spacing=11;vg.childControlHeight=true;vg.childForceExpandHeight=false;vg.childControlWidth=true;vg.childForceExpandWidth=true;ContentSizeFitter fit=body.AddComponent<ContentSizeFitter>();fit.verticalFit=ContentSizeFitter.FitMode.PreferredSize;scroll.content=content;}
        private void Refresh(){if(content==null)return;for(int i=content.childCount-1;i>=0;i--)Destroy(content.GetChild(i).gameObject);ProgressionService s=ProgressionDirector.Instance?.Service;if(s==null){Heading("PROGRESSION","Initializing…");return;}Heading(page==0?"TECHNICIAN CAREER":page==1?"CERTIFICATION SKILLS":"ACHIEVEMENTS","Level "+s.Level+" · "+s.Certification+" · XP "+GameRuntime.Instance.State.experience+" · reputation "+GameRuntime.Instance.State.reputation);if(page==0)Career(s);else if(page==1)Skills(s);else Achievements(s);}
        private void Career(ProgressionService s){float p=s.LevelProgress01();Card("LEVEL "+s.Level,"Progress to next level "+Mathf.RoundToInt(p*100)+"%\nCertification: "+s.Certification+"\nEarned certification points "+s.EarnedSkillPoints+" · spent "+s.SpentSkillPoints+" · available "+s.AvailableSkillPoints,new Color(.20f,.82f,.48f,1f));Card("WORKSHOP CAPABILITY","Bench "+GameRuntime.Instance.State.workshop.benchLevel+" · diagnostics "+GameRuntime.Instance.State.workshop.diagnosticsLevel+" · board repair "+GameRuntime.Instance.State.workshop.boardRepairLevel+" · storage "+GameRuntime.Instance.State.workshop.storageLevel+"\nHardware unlocked "+GameRuntime.Instance.State.unlockedPartIds.Count+" / "+GameRuntime.Instance.Catalog.All.Count,Color.white);Section("CAREER LADDER");string[] ladder={"Lv 1 · Apprentice Technician","Lv 5 · Workshop Technician","Lv 9 · Certified Diagnostics Tech","Lv 14 · Senior Workshop Engineer","Lv 20 · Master Systems Engineer"};foreach(string x in ladder)Card(x,"Experience and reputation both contribute to workshop authority.",Color.white);}
        private void Skills(ProgressionService s){Card("CERTIFICATION POINTS",s.AvailableSkillPoints+" point(s) available. One point is earned every two technician levels after level 1.",s.AvailableSkillPoints>0?new Color(.20f,.82f,.48f,1f):Color.white);foreach(ProgressionNode n in ProgressionService.Nodes){bool unlocked=s.IsUnlocked(n.id);bool eligible=s.Level>=n.requiredLevel&&GameRuntime.Instance.State.reputation>=n.requiredReputation&&s.AvailableSkillPoints>0;GameObject row=UI("Skill",content);row.AddComponent<Image>().color=new Color(.095f,.115f,.145f,1f);HorizontalLayoutGroup h=row.AddComponent<HorizontalLayoutGroup>();h.padding=new RectOffset(16,10,10,10);h.spacing=10;h.childControlHeight=true;h.childForceExpandHeight=true;LayoutElement rl=row.AddComponent<LayoutElement>();rl.preferredHeight=86;GameObject text=UI("Text",row.transform);VerticalLayoutGroup tv=text.AddComponent<VerticalLayoutGroup>();tv.childForceExpandHeight=false;LayoutElement tl=text.AddComponent<LayoutElement>();tl.flexibleWidth=1;Text a=Text((unlocked?"✓ ":"")+n.title,text.transform,20,TextAnchor.MiddleLeft,unlocked?new Color(.25f,.86f,.50f,1f):Color.white);a.fontStyle=FontStyle.Bold;Text b=Text(n.description+"\nRequires level "+n.requiredLevel+" · reputation "+n.requiredReputation,text.transform,15,TextAnchor.UpperLeft,new Color(.64f,.72f,.80f,1f));b.horizontalOverflow=HorizontalWrapMode.Wrap;b.verticalOverflow=VerticalWrapMode.Overflow;if(!unlocked){string id=n.id;Button u=Button(eligible?"UNLOCK":"LOCKED",row.transform,eligible?new Color(.10f,.48f,.70f,1f):new Color(.24f,.26f,.29f,1f),()=>{ProgressionDirector.Instance?.Unlock(id);Refresh();});LayoutElement ul=u.gameObject.AddComponent<LayoutElement>();ul.preferredWidth=140;u.interactable=eligible;}}
        }
        private void Achievements(ProgressionService s){var list=s.AchievementSnapshot();Card("ACHIEVEMENTS",list.Count+" currently earned. Achievements are derived from persistent gameplay state rather than manually awarded flags.",new Color(.82f,.70f,.22f,1f));if(list.Count==0)Card("NONE YET","Complete contracts, grow cash reserves, reputation and workshop capability.",Color.white);foreach(string a in list)Card("✓ "+a,"Persistent state criterion currently satisfied.",new Color(.20f,.82f,.48f,1f));Section("RECENT MILESTONES");foreach(string m in GameRuntime.Instance.State.milestones.AsEnumerable().Reverse().Where(x=>!x.StartsWith("SKILL:",StringComparison.Ordinal)).Take(20))Card(m,"",Color.white);}
        private void Heading(string a,string b){Text t=Block(a,32,Color.white,55);t.fontStyle=FontStyle.Bold;Block(b,19,new Color(.56f,.65f,.73f,1f),38);}private void Section(string a){Text t=Block(a,22,new Color(.10f,.64f,.92f,1f),42);t.fontStyle=FontStyle.Bold;}private void Card(string title,string sub,Color c){GameObject g=UI("Card",content);g.AddComponent<Image>().color=new Color(.095f,.115f,.145f,1f);VerticalLayoutGroup v=g.AddComponent<VerticalLayoutGroup>();v.padding=new RectOffset(18,18,11,12);v.spacing=4;v.childControlHeight=true;v.childForceExpandHeight=false;LayoutElement le=g.AddComponent<LayoutElement>();le.minHeight=68;Text a=Text(title,g.transform,21,TextAnchor.MiddleLeft,c);a.fontStyle=FontStyle.Bold;if(!string.IsNullOrEmpty(sub)){Text b=Text(sub,g.transform,17,TextAnchor.UpperLeft,new Color(.66f,.73f,.80f,1f));b.horizontalOverflow=HorizontalWrapMode.Wrap;b.verticalOverflow=VerticalWrapMode.Overflow;}}private Text Block(string value,int size,Color c,float height){Text t=Text(value,content,size,TextAnchor.MiddleLeft,c);LayoutElement l=t.gameObject.AddComponent<LayoutElement>();l.preferredHeight=height;return t;}private Button Button(string label,Transform p,Color c,Action a){GameObject g=UI("Button_"+label,p);Image i=g.AddComponent<Image>();i.color=c;Button b=g.AddComponent<Button>();b.targetGraphic=i;if(a!=null)b.onClick.AddListener(()=>a());Text t=Text(label,g.transform,16,TextAnchor.MiddleCenter,Color.white);Stretch(t.rectTransform,5);t.raycastTarget=false;return b;}private Text Text(string value,Transform p,int size,TextAnchor align,Color c){GameObject g=UI("Text",p);Text t=g.AddComponent<Text>();t.font=font;t.text=value;t.fontSize=size;t.alignment=align;t.color=c;t.raycastTarget=false;return t;}private GameObject UI(string n,Transform p){GameObject g=new GameObject(n,typeof(RectTransform));g.transform.SetParent(p,false);return g;}private static void Stretch(RectTransform r,float i=0){r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.offsetMin=new Vector2(i,i);r.offsetMax=new Vector2(-i,-i);}private static void EnsureEventSystem(){if(FindAnyObjectByType<EventSystem>()!=null)return;GameObject e=new GameObject("EventSystem");e.AddComponent<EventSystem>();e.AddComponent<StandaloneInputModule>();DontDestroyOnLoad(e);}
    }
}
